package com.aveycole.agentlooper;

import android.app.*;
import android.content.*;
import android.content.pm.ServiceInfo;
import android.media.*;
import android.media.audiofx.*;
import android.media.projection.*;
import android.os.*;
import java.io.*;

/** Foreground ownership lets recording continue when switching to the captured app. */
public final class AudioService extends Service {
    public static final LoopEngine engine=new LoopEngine();
    public static volatile AudioService current;
    public static volatile boolean restored;
    public static volatile int mode=0,inputId=0,outputId=0,left=0,right=0; // mic, apps, mic+apps
    public static volatile boolean monitor=false;
    public static volatile double monitorGain=1;
    double monitorSmooth;
    public volatile String route="";
    public volatile boolean ready;
    private AudioRecord mic,apps;
    private AudioTrack output;
    private MediaProjection projection;
    private Thread worker;
    private volatile boolean running;
    private int channels=1;
    private final Handler handler=new Handler(Looper.getMainLooper());
    private AudioManager manager;
    private int lastDevices;
    private void devicesChanged(){int signature=0;for(AudioDeviceInfo d:manager.getDevices(AudioManager.GET_DEVICES_ALL))signature=signature*31+d.getId();if(signature!=lastDevices){lastDevices=signature;queueReopen();}}
    private PowerManager.WakeLock wake;
    private final AudioDeviceCallback devices=new AudioDeviceCallback(){@Override public void onAudioDevicesAdded(AudioDeviceInfo[] d){}@Override public void onAudioDevicesRemoved(AudioDeviceInfo[] devices){for(AudioDeviceInfo d:devices)if(d.getId()==inputId||d.getId()==outputId){if(d.getId()==outputId)outputId=0;queueReopen();break;}}};
    private final Runnable reopenTask=()->reopen();
    @Override public void onCreate(){super.onCreate();current=this;manager=(AudioManager)getSystemService(AUDIO_SERVICE);NotificationManager n=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);n.createNotificationChannel(new NotificationChannel("audio","Audio session",NotificationManager.IMPORTANCE_LOW));if(!restored){try{File f=new File(getFilesDir(),"session.agl");if(f.exists())try(InputStream in=new FileInputStream(f)){engine.load(in);}}catch(Exception e){engine.message="Session restore: "+e.getMessage();}restored=true;}for(AudioDeviceInfo d:manager.getDevices(AudioManager.GET_DEVICES_ALL))lastDevices=lastDevices*31+d.getId();manager.registerAudioDeviceCallback(devices,handler);PowerManager pm=(PowerManager)getSystemService(POWER_SERVICE);wake=pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"AgentLooper:audio");}
    private Notification notification(){Intent open=new Intent(this,MainActivity.class);Intent stop=new Intent(this,AudioService.class).setAction("STOP");return new Notification.Builder(this,"audio").setContentTitle("Agent Looper").setContentText(mode==0?"Microphone / USB audio":mode==1?"Other-app audio capture":"Mic + other-app audio capture").setSmallIcon(android.R.drawable.ic_media_play).setOngoing(true).setContentIntent(PendingIntent.getActivity(this,0,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT)).addAction(new Notification.Action.Builder(null,"Stop",PendingIntent.getService(this,1,stop,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT)).build()).build();}
    private void foreground(boolean projecting){int types=ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK;if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)==android.content.pm.PackageManager.PERMISSION_GRANTED)types|=ServiceInfo.FOREGROUND_SERVICE_TYPE_MICROPHONE;if(projecting)types|=ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION;if(Build.VERSION.SDK_INT>=29)startForeground(1,notification(),types);else startForeground(1,notification());}
    @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent!=null&&"STOP".equals(intent.getAction())){stopSelf();return START_NOT_STICKY;}try{boolean grant=intent!=null&&intent.hasExtra("grant");foreground(grant||projection!=null);if(grant&&Build.VERSION.SDK_INT>=29){closeAudio();if(projection!=null){projection.unregisterCallback(projectionCallback);projection.stop();}MediaProjectionManager pm=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);projection=pm.getMediaProjection(Activity.RESULT_OK,intent.getParcelableExtra("grant"));projection.registerCallback(projectionCallback,handler);}reopen();}catch(Exception e){engine.message="Audio: "+e.getMessage();}return START_NOT_STICKY;}
    private final MediaProjection.Callback projectionCallback=new MediaProjection.Callback(){@Override public void onStop(){projection=null;mode=0;synchronized(engine){engine.finish(0,false);engine.finish(1,false);}engine.message="App capture ended";queueReopen();}};
    public void endCapture(){closeAudio();if(projection!=null){projection.unregisterCallback(projectionCallback);projection.stop();projection=null;}mode=0;queueReopen();}
    public void queueReopen(){handler.removeCallbacks(reopenTask);handler.postDelayed(reopenTask,350);}
    public AudioDeviceInfo find(int id,boolean input){for(AudioDeviceInfo d:manager.getDevices(input?AudioManager.GET_DEVICES_INPUTS:AudioManager.GET_DEVICES_OUTPUTS))if(d.getId()==id)return d;return null;}
    private AudioRecord microphone(){AudioDeviceInfo device=find(inputId,true);int count=device==null?1:Math.max(1,Math.max(left,right)+1);if(device!=null){for(int c:device.getChannelCounts())if(c>=count){count=c;break;}}count=Math.min(24,count);int mask=count==1?AudioFormat.CHANNEL_IN_MONO:AudioFormat.CHANNEL_IN_STEREO;AudioFormat.Builder format=new AudioFormat.Builder().setEncoding(AudioFormat.ENCODING_PCM_FLOAT).setSampleRate(LoopEngine.RATE);if(count>2)format.setChannelIndexMask((1<<count)-1);else format.setChannelMask(mask);int source="true".equals(manager.getProperty(AudioManager.PROPERTY_SUPPORT_AUDIO_SOURCE_UNPROCESSED))?MediaRecorder.AudioSource.UNPROCESSED:MediaRecorder.AudioSource.VOICE_RECOGNITION;AudioRecord r=new AudioRecord.Builder().setAudioSource(source).setAudioFormat(format.build()).setBufferSizeInBytes(Math.max(32768,count*4096)).build();if(r.getState()!=AudioRecord.STATE_INITIALIZED){r.release();throw new IllegalStateException("Input format unavailable");}if(device!=null&&!r.setPreferredDevice(device)){r.release();throw new IllegalStateException("Input route unavailable");}channels=r.getChannelCount();if(left>=channels||right>=channels){r.release();throw new IllegalStateException("Selected channel unavailable");}int session=r.getAudioSessionId();if(AutomaticGainControl.isAvailable()){AutomaticGainControl fx=AutomaticGainControl.create(session);if(fx!=null){fx.setEnabled(false);fx.release();}}if(NoiseSuppressor.isAvailable()){NoiseSuppressor fx=NoiseSuppressor.create(session);if(fx!=null){fx.setEnabled(false);fx.release();}}return r;}
    private void reopen(){closeAudio();if(worker!=null&&worker.isAlive())return;synchronized(engine){engine.finish(0,false);engine.finish(1,false);}try{if(inputId!=0&&find(inputId,true)==null){inputId=0;left=right=0;engine.message="Input disconnected — using microphone";}foreground(projection!=null);if(mode>0&&projection==null){engine.message="Choose Other apps again to allow capture";mode=0;}if(mode!=1&&checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)==android.content.pm.PackageManager.PERMISSION_GRANTED)mic=microphone();if(mode>0&&Build.VERSION.SDK_INT>=29){AudioPlaybackCaptureConfiguration config=new AudioPlaybackCaptureConfiguration.Builder(projection).addMatchingUsage(AudioAttributes.USAGE_MEDIA).addMatchingUsage(AudioAttributes.USAGE_GAME).addMatchingUsage(AudioAttributes.USAGE_UNKNOWN).excludeUid(android.os.Process.myUid()).build();apps=new AudioRecord.Builder().setAudioFormat(new AudioFormat.Builder().setEncoding(AudioFormat.ENCODING_PCM_FLOAT).setSampleRate(LoopEngine.RATE).setChannelMask(AudioFormat.CHANNEL_IN_STEREO).build()).setAudioPlaybackCaptureConfig(config).setBufferSizeInBytes(32768).build();}AudioAttributes.Builder attributes=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC);if(Build.VERSION.SDK_INT>=29)attributes.setAllowedCapturePolicy(AudioAttributes.ALLOW_CAPTURE_BY_NONE);output=new AudioTrack.Builder().setAudioAttributes(attributes.build()).setAudioFormat(new AudioFormat.Builder().setEncoding(AudioFormat.ENCODING_PCM_FLOAT).setSampleRate(LoopEngine.RATE).setChannelMask(AudioFormat.CHANNEL_OUT_STEREO).build()).setBufferSizeInBytes(Math.max(8192,AudioTrack.getMinBufferSize(LoopEngine.RATE,AudioFormat.CHANNEL_OUT_STEREO,AudioFormat.ENCODING_PCM_FLOAT))).setTransferMode(AudioTrack.MODE_STREAM).setPerformanceMode(AudioTrack.PERFORMANCE_MODE_LOW_LATENCY).build();AudioDeviceInfo target=find(outputId,false);if(target!=null&&!output.setPreferredDevice(target))throw new IllegalStateException("Output route unavailable");if(mic!=null)mic.startRecording();if(apps!=null)apps.startRecording();output.play();running=true;ready=true;route=mode==0?"MIC / USB":mode==1?"OTHER APPS":"MIC + APPS";if(!wake.isHeld())wake.acquire();worker=new Thread(this::runAudio,"Agent Looper audio");worker.start();}catch(Exception e){engine.message="Audio: "+e.getMessage();closeAudio();}}
    private int read(AudioRecord r,float[] data,int n){int at=0;while(running&&at<n){int got=r.read(data,at,n-at,AudioRecord.READ_BLOCKING);if(got<0)throw new IllegalStateException("Audio input stopped ("+got+")");if(got==0)continue;at+=got;}return at;}
    private void runAudio(){android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_URGENT_AUDIO);int selectedLeft=left,selectedRight=right;float[] input=new float[256*Math.max(2,channels)],app=new float[512],stereo=new float[512],out=new float[512];try{while(running){if(mic!=null)read(mic,input,256*channels);if(apps!=null)read(apps,app,512);for(int i=0;i<256;i++){stereo[i*2]=(mic==null?0:input[i*channels+selectedLeft])+(apps==null?0:app[i*2]);stereo[i*2+1]=(mic==null?0:input[i*channels+selectedRight])+(apps==null?0:app[i*2+1]);}engine.process(stereo,2,0,1,out,256);for(int i=0;i<256;i++){monitorSmooth+=((monitor&&mic!=null?monitorGain:0)-monitorSmooth)*.004;if(mic!=null){out[i*2]=Math.max(-1,Math.min(1,out[i*2]+(float)(input[i*channels+selectedLeft]*monitorSmooth)));out[i*2+1]=Math.max(-1,Math.min(1,out[i*2+1]+(float)(input[i*channels+selectedRight]*monitorSmooth)));}}float finalPeak=0;for(float sample:out)finalPeak=Math.max(finalPeak,Math.abs(sample));engine.outputPeak=finalPeak;int at=0;while(running&&at<out.length){int n=output.write(out,at,out.length-at,AudioTrack.WRITE_BLOCKING);if(n<0)throw new IllegalStateException("Audio output stopped ("+n+")");at+=n;}}}catch(Exception e){if(running)engine.message=e.getMessage();}finally{ready=false;}}
    private void closeAudio(){ready=false;running=false;if(mic!=null)try{mic.stop();}catch(Exception ignored){}if(apps!=null)try{apps.stop();}catch(Exception ignored){}if(output!=null)try{output.pause();output.flush();}catch(Exception ignored){}if(worker!=null){try{worker.join(1500);}catch(InterruptedException ignored){}if(worker.isAlive()){engine.message="Audio thread did not stop";return;}worker=null;}if(mic!=null){mic.release();mic=null;}if(apps!=null){apps.release();apps=null;}if(output!=null){output.release();output=null;}if(wake!=null&&wake.isHeld())wake.release();}
    public void save(){new Thread(()->{try{LoopEngine copy;synchronized(engine){if(engine.banks[0].recording||engine.banks[1].recording)return;copy=engine.snapshot();}File tmp=new File(getFilesDir(),"session.tmp"),dst=new File(getFilesDir(),"session.agl");try(OutputStream out=new FileOutputStream(tmp)){copy.save(out);}if(!tmp.renameTo(dst))throw new IOException("Could not save session");}catch(Exception e){engine.message="Save: "+e.getMessage();}},"Agent Looper save").start();}
    @Override public void onDestroy(){handler.removeCallbacksAndMessages(null);manager.unregisterAudioDeviceCallback(devices);closeAudio();synchronized(engine){engine.finish(0,false);engine.finish(1,false);for(LoopEngine.Bank b:engine.banks)b.playing=false;}save();if(projection!=null){projection.unregisterCallback(projectionCallback);projection.stop();projection=null;}monitor=false;current=null;super.onDestroy();}
    @Override public IBinder onBind(Intent i){return null;}
    @Override public void onTaskRemoved(Intent rootIntent){closeAudio();stopSelf();super.onTaskRemoved(rootIntent);}
}
